def rollback_failed_worker_deployments():
    offset = 0
    limit = 50
    rolled_back_count = 0

    while True:
        # List failed deployments for 'worker' in 'staging'
        deployments = list_deployments(service='worker', env='staging', status='failed', limit=limit, offset=offset)

        items = deployments.get('items', [])
        if not items:
            break

        for dep in items:
            # Check if it's already rolled back (though status is 'failed', good to be safe)
            if not dep.get('rolled_back'):
                result = rollback_deployment(dep['id'])
                if result.get('ok'):
                    rolled_back_count += 1

        # Check if we've reached the end
        if len(items) < limit:
            break

        offset += limit
        # Safety break to prevent infinite loop if total is huge
        if offset > 1000:
            break

    print(f"Rolled back {rolled_back_count} deployments.")

rollback_failed_worker_deployments()

def restock_low_stock_skus():
    offset = 0
    limit = 100
    restocked_count = 0

    while True:
        # Fetch a page of SKUs
        result = list_skus(limit=limit, offset=offset)
        items = result.get('items', [])

        if not items:
            break

        for item in items:
            sku = item['sku']
            stock = item['stock']
            if stock < 40:
                restock_success = restock(sku=sku, quantity=50)
                if restock_success.get('ok'):
                    restocked_count += 1

        # Check if we've reached the end
        if offset + limit >= result.get('total', 0):
            break
        offset += limit

    print(f"Restocked {restocked_count} SKUs.")

restock_low_stock_skus()

