def update_acme_tickets():
    offset = 0
    limit = 50
    updated_count = 0

    while True:
        # We need to find 'open' tickets with 'low' priority for customer 'Acme'
        # list_tickets allows filtering by status and priority
        tickets_data = list_tickets(status='open', priority='low', limit=limit, offset=offset)
        items = tickets_data.get('items', [])

        if not items:
            break

        for ticket in items:
            if ticket.get('customer') == 'Acme':
                # Update priority to high
                result = triage_ticket(ticket['id'], 'high')
                if result.get('ok'):
                    updated_count += 1

        # Check if we've reached the end
        if offset + limit >= tickets_data.get('total', 0):
            break

        offset += limit

    print(f"Updated {updated_count} tickets.")

update_acme_tickets()

