def get_most_assigned_bug_person():
    bug_counts = {}
    offset = 0
    limit = 50

    while True:
        # Fetch open bug issues
        result = list_issues(repo='cinder', state='open', label='bug', limit=limit, offset=offset)
        items = result.get('items', [])

        if not items:
            break

        for issue in items:
            assignee_id = issue.get('assignee')
            if assignee_id:
                bug_counts[assignee_id] = bug_counts.get(assignee_id, 0) + 1

        # Check if we've reached the end
        if len(items) < limit:
            break
        offset += limit

    if not bug_counts:
        return "No open bug issues found with assignees."

    # Find the person with the most bugs
    max_bugs = max(bug_counts.values())
    top_assignees = [uid for uid, count in bug_counts.items() if count == max_bugs]

    # Get the name of the first top assignee
    top_user_id = top_assignees[0]
    user_info = lookup_user(top_user_id)
    return user_info.get('name')

